<?php

namespace PryTax\Services\Invoices;

use PryTax\Models\Invoice;
use PryTax\Models\Profile;

/**
 * Class InvoicePreview.
 *
 * Renders the PDF of a draft generated by PryTax, which the app previews before the freeze: as the freeze would print
 * it now, with the number it would get and its own settings, marked as a draft across every page, with nothing stored.
 *
 * @author Andrii Prykhodko <andriichello@gmail.com>
 * @package PryTax\Services\Invoices
 */
class InvoicePreview
{
    /**
     * InvoicePreview constructor.
     *
     * @param InvoiceFreezer $freezer
     * @param InvoicePdfRenderer $renderer
     */
    public function __construct(
        protected InvoiceFreezer $freezer,
        protected InvoicePdfRenderer $renderer
    ) {}

    /**
     * Render the PDF of the draft's preview.
     *
     * @param Profile $profile
     * @param Invoice $draft
     *
     * @return string
     */
    public function render(Profile $profile, Invoice $draft): string
    {
        // In memory only: the number the freeze would give, and the snapshot it would take
        $draft->forceFill(['number' => $draft->number_preview]);
        $draft->snapshot = $this->freezer->snapshot($profile, $draft);

        return $this->renderer->render($draft, InvoicePdfRenderer::TEMPLATE_VERSION, draft: true);
    }
}
